#include <stdio.h>

int apply(char op, int a, int b) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        default: return a / b;
    }
}

int main() {
    const char *expr = "95+2*";
    int stack[10];
    int top = -1;
    for (int i = 0; expr[i] != '\0'; i++) {
        char c = expr[i];
        if (c >= '0' && c <= '9') {
            stack[++top] = c - '0';
        } else {
            int b = stack[top--];
            int a = stack[top--];
            stack[++top] = apply(c, a, b);
        }
    }
    printf("%d\n", stack[top]);
    return 0;
}
